// callBundle.ts: the Calls v1 crypto binding, ported from salt-fe's callCrypto.js. The fixture is
// generated BY salt-fe's implementation (tests/fixtures/gen-call-bundle-fixture.mjs), so these tests
// prove byte compatibility in both directions, not just a round trip.
const test = require("node:test");
const assert = require("node:assert");
const fs = require("node:fs");
const path = require("node:path");
const openpgp = require("openpgp");
const sdk = require("../dist/index.js");

const F = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures", "call_bundle_vectors.json"), "utf8"));
const NOW_MS = F.offer_bundle.ts * 1000;

test("fixture: the SDK reads an offer signed and encrypted by salt-fe", async () => {
  const r = await sdk.decryptAndVerify({ armored: F.fe_offer, decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.person.publicKey });
  assert.equal(r.signatureValid, true);
  assert.deepEqual(r.bundle, F.offer_bundle);
  assert.equal(sdk.isBundleFresh({ bundle: r.bundle, expectedCallId: "call-session-1", now: NOW_MS }), true);
  assert.equal(sdk.fingerprintsMatch(r.bundle.dtls_fingerprints, r.bundle.sdp), true);
});

test("fixture: salt-fe's legacy 'salt'-locked key signs and the SDK verifies it", async () => {
  const r = await sdk.decryptAndVerify({ armored: F.fe_legacy_offer, decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.legacy.publicKey });
  assert.equal(r.signatureValid, true);
  assert.deepEqual(r.bundle, F.offer_bundle);
});

test("fixture: what the SDK signs is the same bundle salt-fe accepted at generation time", async () => {
  // The generator asserted salt-fe's decryptAndVerify accepts these; here the SDK reads its own output.
  const a = await sdk.decryptAndVerify({ armored: F.sdk_answer, decryptionPrivateKey: F.keys.person.privateKey, senderPublicKey: F.keys.device.publicKey });
  assert.equal(a.signatureValid, true);
  assert.deepEqual(a.bundle, F.answer_bundle);
  const l = await sdk.decryptAndVerify({ armored: F.sdk_legacy_answer, decryptionPrivateKey: F.keys.person.privateKey, senderPublicKey: F.keys.legacy.publicKey });
  assert.equal(l.signatureValid, true);
});

test("fixture: SDK fingerprint parsing equals salt-fe's on the same SDP", () => {
  assert.deepEqual(sdk.parseSdpFingerprints(F.offer_sdp), F.fe_parse_offer_fingerprints);
  assert.equal(sdk.fingerprintsMatch(F.offer_bundle.dtls_fingerprints, F.offer_sdp), F.fe_fingerprints_match);
});

test("armored output has the shape salt-fe's payload field carries: one signed+encrypted PGP message", async () => {
  const armored = await sdk.signAndEncrypt({ bundle: F.answer_bundle, signingPrivateKey: F.keys.device.privateKey, receiverPublicKey: F.keys.person.publicKey });
  assert.match(armored, /^-----BEGIN PGP MESSAGE-----/);
  const priv = await openpgp.readPrivateKey({ armoredKey: F.keys.person.privateKey });
  const msg = await openpgp.readMessage({ armoredMessage: armored });
  const { data, signatures } = await openpgp.decrypt({ message: msg, decryptionKeys: priv, verificationKeys: await openpgp.readKey({ armoredKey: F.keys.device.publicKey }) });
  assert.equal(data, JSON.stringify(F.answer_bundle), "plain JSON.stringify of the bundle, insertion order kept, as salt-fe writes it");
  await signatures[0].verified;
});

test("round trip: sign then encrypt, decrypt then verify", async () => {
  const bundle = sdk.buildCallBundle({ callId: "c1", kind: "watch", sdp: F.offer_sdp });
  const armored = await sdk.signAndEncrypt({ bundle, signingPrivateKey: F.keys.person.privateKey, receiverPublicKey: F.keys.device.publicKey });
  const r = await sdk.decryptAndVerify({ armored, decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.person.publicKey });
  assert.equal(r.signatureValid, true);
  assert.deepEqual(r.bundle, bundle);
  assert.equal(sdk.isBundleFresh({ bundle: r.bundle, expectedCallId: "c1" }), true);
});

test("a signature from the wrong key fails closed, never throws", async () => {
  const r = await sdk.decryptAndVerify({ armored: F.fe_offer, decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.device.publicKey });
  assert.equal(r.signatureValid, false);
  assert.ok(r.bundle, "the bundle still decrypts; callers must check signatureValid");
});

test("a message for another key, or garbage, comes back null and invalid", async () => {
  const wrong = await sdk.decryptAndVerify({ armored: F.fe_offer, decryptionPrivateKey: F.keys.person.privateKey, senderPublicKey: F.keys.person.publicKey });
  assert.deepEqual(wrong, { bundle: null, signatureValid: false });
  const junk = await sdk.decryptAndVerify({ armored: "not pgp", decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.person.publicKey });
  assert.deepEqual(junk, { bundle: null, signatureValid: false });
});

test("a payload that decrypts but is not JSON is invalid", async () => {
  const armored = await sdk.signAndEncrypt({ bundle: "not an object", signingPrivateKey: F.keys.person.privateKey, receiverPublicKey: F.keys.device.publicKey });
  // JSON.stringify("not an object") is valid JSON (a string); a real non-JSON body needs raw encrypt.
  const raw = await openpgp.encrypt({
    message: await openpgp.createMessage({ text: "{not json" }),
    encryptionKeys: await openpgp.readKey({ armoredKey: F.keys.device.publicKey }),
    signingKeys: await openpgp.readPrivateKey({ armoredKey: F.keys.person.privateKey }),
  });
  assert.deepEqual(await sdk.decryptAndVerify({ armored: raw, decryptionPrivateKey: F.keys.device.privateKey, senderPublicKey: F.keys.person.publicKey }), { bundle: null, signatureValid: false });
  assert.ok(armored);
});

test("freshness: 5 minute window on ts seconds, call id binding, type check", () => {
  const b = { ts: 1_000_000, call_id: "c" };
  const at = (s) => s * 1000;
  assert.equal(sdk.isBundleFresh({ bundle: b, now: at(1_000_000) }), true);
  assert.equal(sdk.isBundleFresh({ bundle: b, now: at(1_000_300) }), true);
  assert.equal(sdk.isBundleFresh({ bundle: b, now: at(1_000_301) }), false);
  assert.equal(sdk.isBundleFresh({ bundle: b, now: at(999_700) }), true);
  assert.equal(sdk.isBundleFresh({ bundle: b, now: at(999_699) }), false);
  assert.equal(sdk.isBundleFresh({ bundle: b, expectedCallId: "other", now: at(1_000_000) }), false);
  assert.equal(sdk.isBundleFresh({ bundle: b, expectedCallId: "c", now: at(1_000_000) }), true);
  assert.equal(sdk.isBundleFresh({ bundle: { ts: "1000000" }, now: at(1_000_000) }), false);
  assert.equal(sdk.isBundleFresh({ bundle: { call_id: "c" }, now: 0 }), false);
  assert.equal(sdk.isBundleFresh({ bundle: null }), false);
  assert.equal(sdk.TS_SKEW_MS, 300_000);
});

test("fingerprints: parsed from CRLF or LF SDP, compared case and whitespace insensitively", () => {
  const crlf = "m=video 9\r\na=fingerprint:sha-256 ab:cd:ef\r\na=mid:0\r\n";
  const lf = "m=video 9\na=fingerprint:sha-256   ab:cd:ef\na=mid:0\n";
  assert.deepEqual(sdk.parseSdpFingerprints(crlf), ["SHA-256 AB:CD:EF"]);
  assert.deepEqual(sdk.parseSdpFingerprints(lf), ["SHA-256 AB:CD:EF"]);
  assert.equal(sdk.fingerprintsMatch(["sha-256 AB:CD:EF"], crlf), true);
  assert.equal(sdk.fingerprintsMatch(["SHA-256 AB:CD:EE"], crlf), false);
  assert.equal(sdk.fingerprintsMatch([], crlf), false);
  assert.equal(sdk.fingerprintsMatch(["SHA-256 AB:CD:EF"], "v=0\r\n"), false);
  assert.equal(sdk.fingerprintsMatch(null, crlf), false);
  // Every fingerprint in the SDP must be signed, not just one.
  const two = crlf + "a=fingerprint:sha-256 11:22\r\n";
  assert.equal(sdk.fingerprintsMatch(["SHA-256 AB:CD:EF"], two), false);
  assert.equal(sdk.fingerprintsMatch(["SHA-256 AB:CD:EF", "SHA-256 11:22"], two), true);
});

test("buildCallBundle derives fingerprints from the SDP, orders fields like salt-fe, and refuses a bare SDP", () => {
  const b = sdk.buildCallBundle({ callId: "c", kind: "watch", sdp: F.offer_sdp, ts: 5, nonce: "n" });
  assert.deepEqual(Object.keys(b), ["v", "call_id", "kind", "sdp", "dtls_fingerprints", "ts", "nonce"]);
  assert.deepEqual(b.dtls_fingerprints, F.fe_parse_offer_fingerprints);
  const re = sdk.buildCallBundle({ callId: "c", kind: "watch", sdp: F.offer_sdp, sdpType: "answer", ts: 5, nonce: "n" });
  assert.deepEqual(Object.keys(re), ["v", "call_id", "kind", "sdp_type", "sdp", "dtls_fingerprints", "ts", "nonce"]);
  assert.throws(() => sdk.buildCallBundle({ callId: "c", kind: "watch", sdp: "v=0\r\n" }), /fingerprint/);
  assert.match(sdk.randomNonce(), /^[0-9a-f]{32}$/);
  assert.notEqual(sdk.randomNonce(), sdk.randomNonce());
  const sig = sdk.buildSignalBundle({ callId: "c", candidates: [{ candidate: "x" }], ts: 5, nonce: "n" });
  assert.deepEqual(Object.keys(sig), ["v", "call_id", "candidates", "ts", "nonce"]);
});

test("senderKeyMatchesContact compares the key's own fingerprint", async () => {
  assert.equal(await sdk.senderKeyMatchesContact({ senderPublicKey: F.keys.person.publicKey, contactPublicKey: F.keys.person.publicKey }), true);
  assert.equal(await sdk.senderKeyMatchesContact({ senderPublicKey: F.keys.person.publicKey, contactPublicKey: F.keys.device.publicKey }), false);
  assert.equal(await sdk.senderKeyMatchesContact({ senderPublicKey: "", contactPublicKey: F.keys.device.publicKey }), false);
  assert.equal(await sdk.senderKeyMatchesContact({ senderPublicKey: "garbage", contactPublicKey: "garbage" }), false);
});
